/**
 * La de Gemini, y es la que le toca a Antigravity a propósito: su CLI guarda
 * su estado en `~/.gemini/` y sus modelos son Gemini — la marca es de quien
 * corre el turno.
 */
export function GeminiMark(props: { size?: number }) {
  // Ids por instancia: la marca se pinta varias veces por pantalla, y dos ids iguales se pisan.
  const id = createUniqueId();
  return (
    <svg
      class="block shrink-0"
      width={props.size ?? 14}
      height={props.size ?? 14}
      viewBox="0 0 65 65"
      fill="none"
      aria-hidden="true"
    >
      <defs>
        <mask id={`${id}-m`} style={{ "mask-type": "alpha" }} maskUnits="userSpaceOnUse" x="0" y="0" width="65" height="65">
          <path d={GEMINI_ESTRELLA} fill="#000" />
        </mask>
        <For each={GEMINI_MANCHAS}>
          {([, , desenfoque], i) => (
            <filter
              id={`${id}-f${i()}`}
              x="-50"
              y="-50"
              width="170"
              height="170"
              filterUnits="userSpaceOnUse"
              color-interpolation-filters="sRGB"
            >
              <feGaussianBlur stdDeviation={desenfoque} />
            </filter>
          )}
        </For>
      </defs>
      <g mask={`url(#${id}-m)`}>
        <For each={GEMINI_MANCHAS}>
          {([d, color], i) => <path d={d} fill={color} filter={`url(#${id}-f${i()})`} />}
        </For>
      </g>
    </svg>
  );
}

/** Logo cuadrado claro y oscuro de https://opencode.ai/brand. */
export function OpenCodeMark(props: { size?: number }) {
  return (
    <>
      <svg class="block shrink-0 dark:hidden" width={props.size ?? 14} height={props.size ?? 14} viewBox="0 0 300 300" aria-hidden="true">
        <g transform="translate(30 0)">
          <path d="M180 240H60V120H180V240Z" fill="#CFCECD" />
          <path d="M180 60H60V240H180V60ZM240 300H0V0H240V300Z" fill="#211E1E" />
        </g>
      </svg>
      <svg class="hidden shrink-0 dark:block" width={props.size ?? 14} height={props.size ?? 14} viewBox="0 0 300 300" aria-hidden="true">
        <g transform="translate(30 0)">
          <path d="M180 240H60V120H180V240Z" fill="#4B4646" />
          <path d="M180 60H60V240H180V60ZM240 300H0V0H240V300Z" fill="#F1ECEC" />
        </g>
      </svg>
    </>
  );
}

/**
 * La marca de un agente, por su id — el único sitio que decide esto. Cuatro
 * pantallas la piden; repartir el `switch` deja a un agente nuevo con marca en
 * unas y sin ella en otras, sin aviso. Un agente desconocido no pinta nada:
 * mejor un hueco que un símbolo que afirme un dueño que no sabemos.
 */
export function MarcaAgente(props: { id: string; size?: number }) {
  return (
    <Switch>
      <Match when={props.id === "claude"}><ClaudeMark size={props.size} /></Match>
      <Match when={props.id === "codex"}><CodexMark size={props.size} /></Match>
      <Match when={props.id === "grok"}><GrokMark size={props.size} /></Match>
      <Match when={props.id === "antigravity"}><GeminiMark size={props.size} /></Match>
      <Match when={props.id === "opencode" || props.id.startsWith("opencode-")}>
        <OpenCodeMark size={props.size} />
      </Match>
    </Switch>
  );
}

/** Lo mismo para proveedores de código y conexiones. */
export function MarcaProveedor(props: { id: string; size?: number }) {
  return (
    <Switch>
      <Match when={props.id === "github"}><GitHubMark size={props.size} /></Match>
      <Match when={props.id === "bitbucket"}><BitbucketMark size={props.size} /></Match>
      <Match when={props.id === "figma"}><FigmaMark size={props.size} /></Match>
      <Match when={props.id === "atlassian"}><AtlassianMark size={props.size} /></Match>
      <Match when={props.id === "excalidraw"}><ExcalidrawMark size={props.size} /></Match>
    </Switch>
  );
}
